import java.io.*;
import java.util.*;

public class B {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        while (sc.hasNext()) {
            int n = sc.nextInt();
            String s = sc.next();
            boolean inParen = false;
            int countWords = 0;
            String longestWord = "";
            String currentWord = "";
            boolean wordFlag = true;
            for (int i = 0; i < n; i++) {
                char ch = s.charAt(i);
                if (ch == '(') {
                    inParen = true;
                    wordFlag = true;
                    currentWord = "";
                } else if (ch == ')') {
                    inParen = false;
                    currentWord = "";
                } else {
                    if (!inParen) {
                        if (ch == '_') {
                            currentWord = "";
                        } else {
                            currentWord += ch;
                        }
                        if (currentWord.length() > longestWord.length()) {
                            longestWord = currentWord;
                        }
                    } else {
                        if (ch == '_') {
                            wordFlag = true;
                        } else {
                            if (wordFlag) {
                                countWords++;
                                wordFlag = false;
                            }
                        }
                    }
                }
            }
            out.println(longestWord.length() + " " + countWords);
        }
        out.flush();
    }
}
